// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAccessRules The access control rules that bear on an entry
	// (GET /access)
	GetAccessRules(c *fiber.Ctx, params GetAccessRulesParams) error
	// ApplyChange Apply a change
	// (POST /changes/apply)
	ApplyChange(c *fiber.Ctx, params ApplyChangeParams) error
	// DetermineChangeOutcome Find out whether a change whose outcome was unknown actually landed
	// (POST /changes/outcome)
	DetermineChangeOutcome(c *fiber.Ctx) error
	// PreviewChange Render a change as LDIF and as an Ansible task
	// (POST /changes/preview)
	//
	// Deprecated: this operation has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	PreviewChange(c *fiber.Ctx) error
	// ApplyChangeset Apply several changes in order
	// (POST /changeset/apply)
	ApplyChangeset(c *fiber.Ctx) error
	// PreviewChangeset Render several changes as one LDIF document and one playbook
	// (POST /changeset/preview)
	PreviewChangeset(c *fiber.Ctx) error
	// CompareEntries What differs between two entries
	// (GET /compare)
	CompareEntries(c *fiber.Ctx, params CompareEntriesParams) error
	// GetConfigEntryModel What the configuration model says about one entry
	// (GET /config/entry)
	GetConfigEntryModel(c *fiber.Ctx, params GetConfigEntryModelParams) error
	// GetConfigIndexes What this server indexes, and what can be done about it
	// (GET /config/indexes)
	GetConfigIndexes(c *fiber.Ctx) error
	// PlanConfigIndex The change that would add an index
	// (POST /config/indexes/candidate)
	PlanConfigIndex(c *fiber.Ctx) error
	// CountEntries Count the entries under a base, up to a limit
	// (GET /count)
	CountEntries(c *fiber.Ctx, params CountEntriesParams) error
	// DiffStates Compare two directory states
	// (POST /diff)
	DiffStates(c *fiber.Ctx) error
	// GetEntry Read one entry
	// (GET /entry)
	GetEntry(c *fiber.Ctx, params GetEntryParams) error
	// ExportAnsible Export an entry or a subtree as a playbook that enforces it
	// (GET /export/ansible)
	ExportAnsible(c *fiber.Ctx, params ExportAnsibleParams) error
	// ExportLdif Export an entry or a subtree as LDIF
	// (GET /export/ldif)
	ExportLdif(c *fiber.Ctx, params ExportLdifParams) error
	// ExportOutline The shape of a subtree, as a tree
	// (GET /export/outline)
	ExportOutline(c *fiber.Ctx, params ExportOutlineParams) error
	// ExportYaml The subtree as nested YAML
	// (GET /export/yaml)
	ExportYaml(c *fiber.Ctx, params ExportYamlParams) error
	// ParseLdif Parse an LDIF document into change records
	// (POST /import/ldif)
	ParseLdif(c *fiber.Ctx) error
	// InventoryValues What values one attribute holds, and how many entries carry each
	// (POST /inventory)
	InventoryValues(c *fiber.Ctx) error
	// ExpandMembers Who is in this group, following nested groups
	// (GET /members)
	ExpandMembers(c *fiber.Ctx, params ExpandMembersParams) error
	// BuildPackage Build a change package from changes
	// (POST /packages/build)
	BuildPackage(c *fiber.Ctx) error
	// InspectPackage Read a change package and check everything that needs no directory
	// (POST /packages/inspect)
	InspectPackage(c *fiber.Ctx) error
	// ValidatePackage Validate a change package against the current directory
	// (POST /packages/validate)
	ValidatePackage(c *fiber.Ctx) error
	// PlanChanges What a set of changes would do, without doing it
	// (POST /plan)
	PlanChanges(c *fiber.Ctx) error
	// GetPasswordPolicy The password policy in force on an entry, and the account's state
	// (GET /policy)
	GetPasswordPolicy(c *fiber.Ctx, params GetPasswordPolicyParams) error
	// Preflight Report what of an artifact would carry across to this directory
	// (POST /preflight)
	Preflight(c *fiber.Ctx) error
	// InspectRecovery Validate a recovery bundle and turn it into changes to plan
	// (POST /recovery/inspect)
	InspectRecovery(c *fiber.Ctx) error
	// ListReferences The entries that name this one, and the attribute each names it by
	// (GET /references)
	ListReferences(c *fiber.Ctx, params ListReferencesParams) error
	// GetReplication What this server records about its own replication
	// (GET /replication)
	GetReplication(c *fiber.Ctx) error
	// GetReplicationConflicts Entries this server has marked as conflicting
	// (GET /replication/conflicts)
	GetReplicationConflicts(c *fiber.Ctx, params GetReplicationConflictsParams) error
	// GetEntryReplication What this server records about one entry's replication
	// (GET /replication/entry)
	GetEntryReplication(c *fiber.Ctx, params GetEntryReplicationParams) error
	// Resolve What could this input be — an entry, or a search
	// (GET /resolve)
	Resolve(c *fiber.Ctx, params ResolveParams) error
	// GetSchema The whole schema, indexed for browsing
	// (GET /schema)
	GetSchema(c *fiber.Ctx) error
	// GetAttributeType One attribute type, with its cross-links resolved
	// (GET /schema/attributetypes/{name})
	GetAttributeType(c *fiber.Ctx, name string) error
	// BuildSchemaChange Build the modification that installs, replaces or removes a definition
	// (POST /schema/change)
	BuildSchemaChange(c *fiber.Ctx) error
	// GetObjectClass One object class, with its cross-links resolved
	// (GET /schema/objectclasses/{name})
	GetObjectClass(c *fiber.Ctx, name string) error
	// GetRequirements What an entry of these object classes must and may hold
	// (GET /schema/requirements)
	GetRequirements(c *fiber.Ctx, params GetRequirementsParams) error
	// Search Search the directory
	// (POST /search)
	Search(c *fiber.Ctx) error
	// DeleteSession Disconnect
	// (DELETE /session)
	DeleteSession(c *fiber.Ctx) error
	// GetSession Describe the current session
	// (GET /session)
	GetSession(c *fiber.Ctx) error
	// CreateSession Connect and bind to a directory
	// (POST /session)
	CreateSession(c *fiber.Ctx) error
	// CaptureSnapshot Capture a subtree as a versioned snapshot
	// (POST /snapshots/capture)
	CaptureSnapshot(c *fiber.Ctx) error
	// CaptureFromAnotherServer Capture another server's configuration
	// (POST /snapshots/capture/from)
	CaptureFromAnotherServer(c *fiber.Ctx) error
	// InspectSnapshot Validate a snapshot and describe it
	// (POST /snapshots/inspect)
	InspectSnapshot(c *fiber.Ctx) error
	// GetSourceOffer Where to get the source of this running instance
	// (GET /source)
	GetSourceOffer(c *fiber.Ctx) error
	// ListChildren List the children of an entry
	// (GET /tree)
	ListChildren(c *fiber.Ctx, params ListChildrenParams) error
	// ListObjectViews The object-aware views this directory supports
	// (GET /views)
	ListObjectViews(c *fiber.Ctx) error
}

